// Match pitch is a broadcast; editing belongs exclusively to the tactics dialog.
function renderTacticalEditor(){
 const host=$('tactical-editor');if(!host||!state)return;
 const canEdit=editable(),rows=positions().filter(row=>!Discipline.dismissed(state).includes(row.id)),chosen=rows.find(row=>row.id===selected);
 host.innerHTML='<h3>선수 배치와 역할</h3><p>선수를 선택한 뒤 좌우·전후 위치를 조정하세요. 경기 중계 화면은 조작되지 않습니다.</p><div class="tactical-pitch" role="group" aria-label="전술 선수 배치">'+rows.map(({id,p,x,y})=>'<button type="button" data-tactical-player="'+id+'" aria-pressed="'+(selected===id)+'" '+(!canEdit?'disabled':'')+' style="left:'+x+'%;top:'+y+'%"><b>'+p.no+'</b><span>'+escapeText(p.name)+'</span></button>').join('')+'</div>'+(chosen?'<fieldset class="tactical-position" '+(!canEdit?'disabled':'')+'><legend>'+escapeText(chosen.p.name)+' 위치</legend><label>좌우 <output>'+chosen.x+'</output><input aria-label="선수 좌우 위치" type="range" data-position-axis="x" min="7" max="93" step="1" value="'+chosen.x+'"></label><label>전후 <output>'+chosen.y+'</output><input aria-label="선수 전후 위치" type="range" data-position-axis="y" min="8" max="92" step="1" value="'+chosen.y+'"></label></fieldset>':'<p>배치판에서 선수를 선택하면 위치 조절과 역할 설정이 열립니다.</p>')+'<p class="tactical-note">배치 조정은 2D 경기장의 기본 위치에 반영됩니다. 경기력은 선수 능력·역할 적합도 안내·팀 전술을 함께 살펴보세요.</p>';
 host.onclick=event=>{const button=event.target.closest('[data-tactical-player]');if(!button||!canEdit)return;selected=button.dataset.tacticalPlayer;save();render();host.querySelector('[data-tactical-player="'+selected+'"]')?.focus({preventScroll:true});};
 host.onchange=event=>{const axis=event.target.dataset.positionAxis,row=positions().find(row=>row.id===selected);if(!axis||!row||!canEdit)return;const value=Number(event.target.value);customPositions[row.p.identity]=axis==='x'?[value,row.y]:[row.x,value];save();render();host.querySelector('[data-position-axis="'+axis+'"]')?.focus({preventScroll:true});};
 host.oninput=event=>{if(event.target.dataset.positionAxis)event.target.previousElementSibling.textContent=event.target.value;};
}
const tacticalEditorHost=document.createElement('section');tacticalEditorHost.id='tactical-editor';$('match-popup-tactics').prepend(tacticalEditorHost);
